**`useTelegramTheme.ts`** — mirrors `themeParams` onto CSS vars and re-applies on `themeChanged` (host can flip to night mode while open); also calls `ready()`/`expand()`.
```ts
import { useEffect } from 'react';

const THEME_KEYS = [
  'bg_color',
  'secondary_bg_color',
  'section_bg_color',
  'text_color',
  'hint_color',
  'link_color',
  'button_color',
  'button_text_color',
  'accent_text_color',
  'destructive_text_color',
  'header_bg_color',
  'bottom_bar_bg_color',
] as const;

function applyThemeVars(): void {
  const webApp = window.Telegram?.WebApp;
  if (!webApp) return;
  const root = document.documentElement;
  THEME_KEYS.forEach((key) => {
    const value = webApp.themeParams[key];
    if (value) {
      root.style.setProperty(`--tg-theme-${key.replace(/_/g, '-')}`, value);
    }
  });
}

export function useTelegramTheme(): void {
  useEffect(() => {
    const webApp = window.Telegram?.WebApp;
    if (!webApp) return;

    applyThemeVars();
    webApp.ready();
    webApp.expand();

    const handleThemeChanged = () => applyThemeVars();
    webApp.onEvent('themeChanged', handleThemeChanged);

    return () => {
      webApp.offEvent('themeChanged', handleThemeChanged);
    };
  }, []);
}
```

