**`CheckoutScreen.tsx`**
```tsx
import React, { useEffect, useMemo, useState } from 'react';
import { CartItem, DeliveryAddress, emptyAddress } from './types';
import { useTelegramTheme } from './useTelegramTheme';
import { useTelegramBackButton } from './useTelegramBackButton';
import { useTelegramMainButton } from './useTelegramMainButton';
import './CheckoutScreen.css';

type FieldErrors = Partial<Record<keyof DeliveryAddress, string>>;

interface CheckoutScreenProps {
  items: CartItem[];
  currencySymbol?: string;
  deliveryFee?: number;
  initialAddress?: DeliveryAddress;
  onBack: () => void;
  onPay: (address: DeliveryAddress, total: number) => Promise<void>;
}

function validateAddress(address: DeliveryAddress): FieldErrors {
  const errors: FieldErrors = {};

  if (!address.fullName.trim()) errors.fullName = 'Enter your full name';
  if (!/^\+?[0-9\s-]{7,15}$/.test(address.phone.trim())) errors.phone = 'Enter a valid phone number';
  if (!address.city.trim()) errors.city = 'Enter a city';
  if (!address.street.trim()) errors.street = 'Enter a street';
  if (!address.house.trim()) errors.house = 'Enter a house number';
  if (!/^[0-9A-Za-z\s-]{3,10}$/.test(address.postalCode.trim())) errors.postalCode = 'Enter a valid postal code';

  return errors;
}

function formatMoney(value: number, symbol: string): string {
  return `${symbol}${value.toFixed(2)}`;
}

export default function CheckoutScreen({
  items,
  currencySymbol = '$',
  deliveryFee = 0,
  initialAddress = emptyAddress,
  onBack,
  onPay,
}: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>(initialAddress);
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  useTelegramTheme();

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0),
    [items]
  );
  const total = subtotal + deliveryFee;

  const errors = useMemo(() => validateAddress(address), [address]);
  const isDirty = useMemo(
    () => JSON.stringify(address) !== JSON.stringify(initialAddress),
    [address, initialAddress]
  );
  const isFormValid = Object.keys(errors).length === 0 && items.length > 0;

  useEffect(() => {
    const webApp = window.Telegram?.WebApp;
    if (!webApp) return;
    if (isDirty) {
      webApp.enableClosingConfirmation();
    } else {
      webApp.disableClosingConfirmation();
    }
  }, [isDirty]);

  function handleChange<K extends keyof DeliveryAddress>(field: K, value: string) {
    setAddress((prev) => ({ ...prev, [field]: value }));
  }

  function handleBlur(field: keyof DeliveryAddress) {
    setTouched((prev) => ({ ...prev, [field]: true }));
  }

  function handleBack() {
    const webApp = window.Telegram?.WebApp;
    if (isDirty && webApp) {
      webApp.showConfirm('Discard your delivery details and go back to the cart?', (confirmed) => {
        if (confirmed) onBack();
      });
      return;
    }
    onBack();
  }

  async function handlePay() {
    const webApp = window.Telegram?.WebApp;

    if (!isFormValid) {
      setTouched({
        fullName: true,
        phone: true,
        city: true,
        street: true,
        house: true,
        apartment: true,
        postalCode: true,
        comment: true,
      });
      webApp?.HapticFeedback.notificationOccurred('error');
      return;
    }

    setSubmitting(true);
    setSubmitError(null);
    webApp?.HapticFeedback.impactOccurred('medium');

    try {
      await onPay(address, total);
      webApp?.HapticFeedback.notificationOccurred('success');
      webApp?.disableClosingConfirmation();
    } catch (error) {
      webApp?.HapticFeedback.notificationOccurred('error');
      const message = error instanceof Error ? error.message : 'Payment failed. Please try again.';
      setSubmitError(message);
      webApp?.showAlert(message);
    } finally {
      setSubmitting(false);
    }
  }

  useTelegramBackButton(true, handleBack);
  useTelegramMainButton({
    text: `Pay ${formatMoney(total, currencySymbol)}`,
    visible: true,
    disabled: !isFormValid || submitting,
    progress: submitting,
    onClick: handlePay,
  });

  const isTelegram = Boolean(window.Telegram?.WebApp);

  return (
    <div className="checkout">
      <header className="checkout__header">
        {!isTelegram && (
          <button type="button" className="checkout__back-link" onClick={handleBack}>
            ← Back to cart
          </button>
        )}
        <h1 className="checkout__title">Checkout</h1>
      </header>

      <section className="checkout__section" aria-label="Order items">
        <h2 className="checkout__section-title">Your order</h2>
        {items.length === 0 ? (
          <p className="checkout__empty">Your cart is empty.</p>
        ) : (
          <ul className="checkout__items">
            {items.map((item) => (
              <li key={item.id} className="checkout__item">
                <img
                  className="checkout__item-image"
                  src={item.imageUrl ?? '/placeholder-item.png'}
                  alt={item.name}
                />
                <div className="checkout__item-info">
                  <span className="checkout__item-name">{item.name}</span>
                  <span className="checkout__item-qty">Qty {item.quantity}</span>
                </div>
                <span className="checkout__item-price">
                  {formatMoney(item.unitPrice * item.quantity, currencySymbol)}
                </span>
              </li>
            ))}
          </ul>
        )}

        <dl className="checkout__totals">
          <div className="checkout__totals-row">
            <dt>Subtotal</dt>
            <dd>{formatMoney(subtotal, currencySymbol)}</dd>
          </div>
          <div className="checkout__totals-row">
            <dt>Delivery</dt>
            <dd>{deliveryFee === 0 ? 'Free' : formatMoney(deliveryFee, currencySymbol)}</dd>
          </div>
          <div className="checkout__totals-row checkout__totals-row--total">
            <dt>Total</dt>
            <dd>{formatMoney(total, currencySymbol)}</dd>
          </div>
        </dl>
      </section>

      <section className="checkout__section" aria-label="Delivery address">
        <h2 className="checkout__section-title">Delivery address</h2>
        <form className="checkout__form" noValidate>
          <div className="checkout__field">
            <label htmlFor="fullName">Full name</label>
            <input
              id="fullName"
              type="text"
              autoComplete="name"
              value={address.fullName}
              onChange={(e) => handleChange('fullName', e.target.value)}
              onBlur={() => handleBlur('fullName')}
              aria-invalid={Boolean(touched.fullName && errors.fullName)}
            />
            {touched.fullName && errors.fullName && (
              <span className="checkout__field-error">{errors.fullName}</span>
            )}
          </div>

          <div className="checkout__field">
            <label htmlFor="phone">Phone number</label>
            <input
              id="phone"
              type="tel"
              autoComplete="tel"
              value={address.phone}
              onChange={(e) => handleChange('phone', e.target.value)}
              onBlur={() => handleBlur('phone')}
              aria-invalid={Boolean(touched.phone && errors.phone)}
            />
            {touched.phone && errors.phone && <span className="checkout__field-error">{errors.phone}</span>}
          </div>

          <div className="checkout__field-row">
            <div className="checkout__field">
              <label htmlFor="city">City</label>
              <input
                id="city"
                type="text"
                autoComplete="address-level2"
                value={address.city}
                onChange={(e) => handleChange('city', e.target.value)}
                onBlur={() => handleBlur('city')}
                aria-invalid={Boolean(touched.city && errors.city)}
              />
              {touched.city && errors.city && <span className="checkout__field-error">{errors.city}</span>}
            </div>

            <div className="checkout__field">
              <label htmlFor="postalCode">Postal code</label>
              <input
                id="postalCode"
                type="text"
                autoComplete="postal-code"
                value={address.postalCode}
                onChange={(e) => handleChange('postalCode', e.target.value)}
                onBlur={() => handleBlur('postalCode')}
                aria-invalid={Boolean(touched.postalCode && errors.postalCode)}
              />
              {touched.postalCode && errors.postalCode && (
                <span className="checkout__field-error">{errors.postalCode}</span>
              )}
            </div>
          </div>

          <div className="checkout__field">
            <label htmlFor="street">Street</label>
            <input
              id="street"
              type="text"
              autoComplete="address-line1"
              value={address.street}
              onChange={(e) => handleChange('street', e.target.value)}
              onBlur={() => handleBlur('street')}
              aria-invalid={Boolean(touched.street && errors.street)}
            />
            {touched.street && errors.street && <span className="checkout__field-error">{errors.street}</span>}
          </div>

          <div className="checkout__field-row">
            <div className="checkout__field">
              <label htmlFor="house">House / building</label>
              <input
                id="house"
                type="text"
                autoComplete="address-line2"
                value={address.house}
                onChange={(e) => handleChange('house', e.target.value)}
                onBlur={() => handleBlur('house')}
                aria-invalid={Boolean(touched.house && errors.house)}
              />
              {touched.house && errors.house && <span className="checkout__field-error">{errors.house}</span>}
            </div>

            <div className="checkout__field">
              <label htmlFor="apartment">Apartment (optional)</label>
              <input
                id="apartment"
                type="text"
                value={address.apartment}
                onChange={(e) => handleChange('apartment', e.target.value)}
                onBlur={() => handleBlur('apartment')}
              />
            </div>
          </div>

          <div className="checkout__field">
            <label htmlFor="comment">Delivery notes (optional)</label>
            <textarea
              id="comment"
              rows={3}
              value={address.comment}
              onChange={(e) => handleChange('comment', e.target.value)}
              onBlur={() => handleBlur('comment')}
            />
          </div>
        </form>

        {submitError && <p className="checkout__submit-error">{submitError}</p>}
      </section>

      {/* Outside Telegram there is no host MainButton, so this fallback bar
          stands in for it. Inside Telegram it never renders — the MainButton
          is the single primary action, and this would duplicate it. */}
      {!isTelegram && (
        <div className="checkout__fallback-bar">
          <button
            type="button"
            className="checkout__fallback-pay"
            disabled={!isFormValid || submitting}
            onClick={handlePay}
          >
            {submitting ? 'Processing…' : `Pay ${formatMoney(total, currencySymbol)}`}
          </button>
        </div>
      )}
    </div>
  );
}
```

